const queryClient = new QueryClient();
const red = 'text-primary';
const bloodGroups = ['A+', 'A-', 'B+', 'B-', 'AB+', 'AB-', 'O+', 'O-'];
const roleLinks = [
  { href: '/donor', label: 'Donor wallet', icon: UserRound },
  { href: '/hospital', label: 'Hospital command', icon: Hospital },
  { href: '/blood-bank', label: 'Blood bank', icon: Database },
  { href: '/lab', label: 'Lab verification', icon: FlaskIcon },
  { href: '/authority', label: 'Grid oversight', icon: ShieldCheck },
  { href: '/founder', label: 'Founder center', icon: ServerCog },
];

function FlaskIcon(props: { size?: number; className?: string }) {
  return <Activity {...props} />;
}

function dateLabel(value?: string | null) {
  if (!value) return 'Not recorded';
  const parsed = new Date(value);
  return Number.isNaN(parsed.getTime()) ? value : parsed.toLocaleDateString('en-IN', { day: '2-digit', month: 'short', year: 'numeric' });
}

function timeLabel(value?: string | null) {
  if (!value) return '—';
  const parsed = new Date(value);
  return Number.isNaN(parsed.getTime()) ? value : parsed.toLocaleTimeString('en-IN', { hour: '2-digit', minute: '2-digit' });
}

function titleCase(value?: string | null) {
  return (value || 'unknown').replaceAll('-', ' ').replace(/\b\w/g, (letter) => letter.toUpperCase());
}

function statusTone(value?: string | null) {
  if (['critical', 'urgent', 'expired', 'quarantined', 'attention', 'unavailable'].includes(value || '')) return 'status status-danger';
  if (['available', 'eligible', 'verified', 'configured', 'fulfilled', 'clear', 'resolved'].includes(value || '')) return 'status status-good';
  return 'status status-watch';
}

function initials(name?: string | null) {
  return (name || 'RK').split(' ').map((part) => part[0]).slice(0, 2).join('').toUpperCase();
}

function LoadingBlock({ rows = 3 }: { rows?: number }) {
  return <div className="space-y-3" data-testid="loading-block">{Array.from({ length: rows }).map((_, index) => <div className="rk-skeleton h-12 w-full" key={index} />)}</div>;
}

function EmptyState({ icon: Icon = ClipboardList, title, detail }: { icon?: typeof ClipboardList; title: string; detail: string }) {
  return <div className="flex flex-col items-center justify-center rounded-xl border border-dashed border-border bg-secondary/35 px-5 py-10 text-center" data-testid="empty-state">
    <span className="mb-3 grid size-11 place-items-center rounded-full bg-card text-muted-foreground shadow-sm"><Icon size={20} /></span>
    <p className="font-semibold">{title}</p><p className="mt-1 max-w-sm text-xs leading-5 text-muted-foreground">{detail}</p>
  </div>;
}

function QueryError({ message = 'The grid could not reach this service.' }: { message?: string }) {
  return <div className="flex items-center gap-3 rounded-xl border border-destructive/25 bg-destructive/5 px-4 py-3 text-sm text-destructive" data-testid="query-error"><AlertCircle size={18} /><span>{message} <button className="ml-2 font-semibold underline" onClick={() => window.location.reload()} data-testid="button-retry">Retry</button></span></div>;
}

function Pill({ children, tone }: { children: ReactNode; tone?: string }) {
  return <span className={tone || 'status status-neutral'}>{children}</span>;
}

function Logo({ compact = false }: { compact?: boolean }) {
  return <Link href="/" className="flex items-center gap-3" data-testid="link-home">
    <span className="relative grid size-9 shrink-0 place-items-center rounded-xl bg-primary text-primary-foreground shadow-[0_8px_20px_hsl(var(--primary)/.24)]"><HeartPulse size={21} strokeWidth={2.5} /><span className="absolute -right-1 -top-1 size-2.5 rounded-full border-2 border-sidebar bg-[hsl(var(--accent))]" /></span>
    {!compact && <span><span className="block font-display text-sm font-bold tracking-tight">Rakt Kavach</span><span className="block font-mono text-[9px] uppercase tracking-[.16em] text-muted-foreground">National blood grid</span></span>}
  </Link>;
}

function Topbar({ onMenu }: { onMenu: () => void }) {
  const [location] = useLocation();
  const [online, setOnline] = useState(true);
  const [notice, setNotice] = useState(false);
  const [language, setLanguage] = useState('EN');
  return <header className="sticky top-0 z-30 flex h-[68px] items-center justify-between border-b border-border bg-background/90 px-4 backdrop-blur md:px-8">
    <div className="flex items-center gap-3"><button className="grid size-9 place-items-center rounded-lg border border-border md:hidden" onClick={onMenu} aria-label="Open navigation" data-testid="button-open-navigation"><Menu size={18} /></button><div className="md:hidden"><Logo compact /></div><div className="hidden md:block"><p className="rk-kicker">Operational view</p><p className="text-sm font-semibold">{location === '/' ? 'Gateway' : titleCase(location.split('/')[1])}</p></div></div>
    <div className="flex items-center gap-2">
      <button onClick={() => setOnline((value) => !value)} className={`hidden items-center gap-2 rounded-full border px-3 py-1.5 text-[11px] font-semibold sm:flex ${online ? 'border-accent/25 bg-accent/10 text-accent' : 'border-primary/25 bg-primary/10 text-primary'}`} data-testid="button-network-status">{online ? <Wifi size={13} /> : <CloudOff size={13} />}{online ? 'Grid online' : 'Offline mode'}</button>
      <button onClick={() => setNotice((value) => !value)} className="relative grid size-9 place-items-center rounded-lg border border-border bg-card text-muted-foreground" aria-label="Notifications" data-testid="button-notifications"><BellRing size={17} />{notice && <span className="absolute right-0 top-10 w-44 rounded-lg border border-border bg-card p-3 text-left text-[11px] font-semibold text-foreground shadow-lg">No new network notices.</span>}</button>
      <button onClick={() => setLanguage((value) => value === 'EN' ? 'HI' : 'EN')} className="grid size-9 place-items-center rounded-lg border border-border bg-card font-mono text-[10px] font-bold text-muted-foreground" aria-label="Change language" data-testid="button-language-toggle">{language}</button>
      <div className="hidden items-center gap-2 border-l border-border pl-3 sm:flex"><span className="grid size-8 place-items-center rounded-full bg-secondary text-xs font-bold text-foreground">RK</span><span className="text-xs font-semibold">Operator</span><ChevronDown size={14} className="text-muted-foreground" /></div>
    </div>
  </header>;
}

function InstallBanner() {
  const [prompt, setPrompt] = useState<any>(null);
  const [dismissed, setDismissed] = useState(false);
  useEffect(() => {
    const capture = (event: Event) => { event.preventDefault(); setPrompt(event); };
    window.addEventListener('beforeinstallprompt', capture);
    return () => window.removeEventListener('beforeinstallprompt', capture);
  }, []);
  if (!prompt || dismissed) return null;
  return <div className="fixed bottom-4 left-4 right-4 z-40 mx-auto flex max-w-md items-center gap-3 rounded-xl border border-border bg-card p-3 shadow-xl md:left-auto md:right-6"><span className="grid size-9 shrink-0 place-items-center rounded-lg bg-primary/10 text-primary"><Zap size={17} /></span><div className="min-w-0 flex-1"><p className="text-xs font-bold">Install the response desk</p><p className="mt-0.5 text-[11px] text-muted-foreground">Keep the grid one tap away when connectivity is uneven.</p></div><button onClick={async () => { await prompt.prompt(); setDismissed(true); }} className="rounded-md bg-primary px-3 py-2 text-[11px] font-bold text-primary-foreground" data-testid="button-install-pwa">Install</button><button onClick={() => setDismissed(true)} className="p-1 text-muted-foreground" aria-label="Dismiss install message" data-testid="button-dismiss-install"><X size={14} /></button></div>;
}

function Sidebar({ open, onClose }: { open: boolean; onClose: () => void }) {
  return <><div className={`fixed inset-0 z-40 bg-foreground/30 transition-opacity md:hidden ${open ? 'opacity-100' : 'pointer-events-none opacity-0'}`} onClick={onClose} /><aside className={`fixed inset-y-0 left-0 z-50 flex w-[260px] flex-col bg-sidebar text-sidebar-foreground transition-transform md:static md:z-0 md:translate-x-0 ${open ? 'translate-x-0' : '-translate-x-full'}`}>
    <div className="flex h-[68px] items-center justify-between border-b border-sidebar-border px-5"><Logo /><button className="md:hidden" onClick={onClose} aria-label="Close navigation" data-testid="button-close-navigation"><X size={18} /></button></div>
    <div className="flex-1 overflow-y-auto px-3 py-6">
      <p className="mb-3 px-3 font-mono text-[10px] uppercase tracking-[.18em] text-sidebar-foreground/45">Network consoles</p>
      <nav className="space-y-1">{roleLinks.map(({ href, label, icon: Icon }) => <Link key={href} href={href} onClick={onClose} className="group flex items-center gap-3 rounded-lg px-3 py-2.5 text-sm text-sidebar-foreground/70 transition-colors hover:bg-sidebar-accent hover:text-sidebar-foreground" data-testid={`link-nav-${href.slice(1)}`}><Icon size={17} className="text-sidebar-foreground/50 group-hover:text-sidebar-primary" /><span>{label}</span></Link>)}</nav>
      <p className="mb-3 mt-8 px-3 font-mono text-[10px] uppercase tracking-[.18em] text-sidebar-foreground/45">Response tools</p>
      <nav className="space-y-1"><Link href="/sos" onClick={onClose} className="flex items-center gap-3 rounded-lg bg-sidebar-primary/12 px-3 py-2.5 text-sm font-semibold text-sidebar-primary" data-testid="link-nav-sos"><Siren size={17} />SOS response<CircleDot size={11} className="ml-auto animate-pulse" /></Link><Link href="/verify/scan" onClick={onClose} className="flex items-center gap-3 rounded-lg px-3 py-2.5 text-sm text-sidebar-foreground/70 hover:bg-sidebar-accent" data-testid="link-nav-verify"><QrCode size={17} />Verify a pass</Link><Link href="/modules" onClick={onClose} className="flex items-center gap-3 rounded-lg px-3 py-2.5 text-sm text-sidebar-foreground/70 hover:bg-sidebar-accent" data-testid="link-nav-modules"><LayoutGrid size={17} />All modules</Link></nav>
    </div>
    <div className="border-t border-sidebar-border p-4"><div className="rounded-xl border border-sidebar-border bg-sidebar-accent/50 p-3"><div className="flex items-center gap-2 text-xs font-semibold"><span className="size-2 rounded-full bg-accent" />Secure session</div><p className="mt-2 text-[10px] leading-4 text-sidebar-foreground/50">Encrypted activity log active across this console.</p></div></div>
  </aside></>;
}

function Shell({ children }: { children: ReactNode }) {
  const [open, setOpen] = useState(false);
  return <div className="rk-noise flex min-h-[100dvh] bg-background text-foreground"><Sidebar open={open} onClose={() => setOpen(false)} /><div className="min-w-0 flex-1"><Topbar onMenu={() => setOpen(true)} /><main className="mx-auto w-full max-w-[1500px] px-4 py-5 md:px-8 md:py-8">{children}</main></div><InstallBanner /></div>;
}

function PageHeader({ eyebrow, title, detail, action }: { eyebrow: string; title: string; detail: string; action?: ReactNode }) {
  return <div className="mb-7 flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p className="rk-kicker text-primary">{eyebrow}</p><h1 className="mt-2 font-display text-2xl font-bold tracking-tight md:text-3xl">{title}</h1><p className="mt-2 max-w-2xl text-sm leading-6 text-muted-foreground">{detail}</p></div>{action}</div>;
}

function MetricCard({ label, value, note, icon: Icon, accent = false }: { label: string; value: ReactNode; note?: string; icon: typeof Activity; accent?: boolean }) {
  return <div className={`rk-card rounded-xl p-4 ${accent ? 'border-primary/30 bg-primary/[.04]' : ''}`} data-testid={`metric-${label.toLowerCase().replaceAll(' ', '-')}`}><div className="flex items-start justify-between"><span className="rk-kicker">{label}</span><span className={`grid size-8 place-items-center rounded-lg ${accent ? 'bg-primary/10 text-primary' : 'bg-secondary text-muted-foreground'}`}><Icon size={16} /></span></div><p className="mt-4 font-display text-2xl font-bold tracking-tight">{value}</p>{note && <p className="mt-1 text-xs text-muted-foreground">{note}</p>}</div>;
}

function SectionCard({ title, eyebrow, action, children, className = '' }: { title: string; eyebrow?: string; action?: ReactNode; children: ReactNode; className?: string }) {
  return <section className={`rk-card rounded-xl ${className}`}><div className="flex items-start justify-between gap-3 border-b border-border px-4 py-4 md:px-5"><div>{eyebrow && <p className="rk-kicker">{eyebrow}</p>}<h2 className="mt-1 text-sm font-bold">{title}</h2></div>{action}</div><div className="p-4 md:p-5">{children}</div></section>;
}

function SummaryStrip({ summary }: { summary?: any }) {
  const metrics = summary?.metrics || {};
  const entries = Object.entries(metrics).slice(0, 4);
  return <div className="grid grid-cols-2 gap-3 lg:grid-cols-4">{entries.length ? entries.map(([key, value], index) => <MetricCard key={key} label={titleCase(key)} value={String(value)} note={index === 0 ? 'Live from grid' : 'Across connected facilities'} icon={[Activity, PackageCheck, UsersRound, Timer][index] || Activity} accent={index === 0} />) : <><MetricCard label="Connected facilities" value="—" note="Awaiting summary" icon={Building2} /><MetricCard label="Available units" value="—" note="Awaiting summary" icon={PackageCheck} /><MetricCard label="Open requests" value="—" note="Awaiting summary" icon={ClipboardList} /><MetricCard label="Active response" value="—" note="Awaiting summary" icon={Siren} /></>}</div>;
}

function Gateway() {
  const health = useHealthCheck();
  return <div className="rk-noise min-h-[100dvh] bg-background"><header className="flex h-20 items-center justify-between border-b border-border px-5 md:px-10"><Logo /><div className="flex items-center gap-3 text-xs text-muted-foreground"><span className={`size-2 rounded-full ${health.isError ? 'bg-primary' : 'bg-accent'}`} />{health.isLoading ? 'Checking grid' : health.isError ? 'Service check unavailable' : 'National grid operational'}<button className="ml-2 hidden rounded-lg border border-border p-2 sm:block" data-testid="button-language"><Languages size={15} /></button></div></header>
    <main className="rk-grid relative overflow-hidden"><div className="absolute -right-20 -top-20 size-80 rounded-full bg-primary/10 blur-3xl" /><div className="mx-auto max-w-6xl px-5 pb-20 pt-14 md:px-10 md:pt-24"><div className="max-w-3xl rk-animate-in"><p className="rk-kicker flex items-center gap-2 text-primary"><span className="size-2 rounded-full bg-primary" />One network. Every critical unit.</p><h1 className="mt-5 font-display text-5xl font-bold leading-[.98] tracking-[-.05em] md:text-7xl">Blood, where it is needed.<span className="block text-primary">When it matters.</span></h1><p className="mt-7 max-w-xl text-base leading-7 text-muted-foreground md:text-lg">Rakt Kavach connects donors, hospitals, banks, laboratories and public authorities into one accountable emergency response grid.</p><div className="mt-9 flex flex-wrap gap-3"><Link href="/sos" className="inline-flex items-center gap-2 rounded-lg bg-primary px-5 py-3 text-sm font-bold text-primary-foreground shadow-[0_12px_30px_hsl(var(--primary)/.22)] transition-transform hover:-translate-y-0.5" data-testid="link-gateway-sos"><Siren size={17} />Open emergency response</Link><Link href="/modules" className="inline-flex items-center gap-2 rounded-lg border border-border bg-card px-5 py-3 text-sm font-bold hover:bg-secondary" data-testid="link-gateway-modules">Explore the grid <ArrowRight size={16} /></Link></div></div>
        <div className="mt-20 grid gap-3 md:grid-cols-3">{[{title: 'For people', detail: 'Carry a verified donor identity and know your next eligible date.', href: '/donor', icon: UserRound}, {title: 'For facilities', detail: 'Match requests to live, verified units without phone-tree delays.', href: '/hospital', icon: Hospital}, {title: 'For the nation', detail: 'See readiness, risk signals and accountability at a glance.', href: '/authority', icon: ShieldCheck}].map(({ title, detail, href, icon: Icon }, index) => <Link href={href} key={href} className={`rk-card rk-animate-in rk-delay-${index + 1} group rounded-xl p-5 transition-transform hover:-translate-y-1`} data-testid={`card-gateway-${title.toLowerCase().replace(' ', '-')}`}><div className="flex items-center justify-between"><span className="grid size-10 place-items-center rounded-lg bg-secondary text-primary"><Icon size={19} /></span><ArrowRight size={17} className="text-muted-foreground transition-transform group-hover:translate-x-1" /></div><h2 className="mt-6 font-display text-lg font-bold">{title}</h2><p className="mt-2 text-sm leading-6 text-muted-foreground">{detail}</p></Link>)}</div>
      </div></main><footer className="flex flex-col justify-between gap-2 border-t border-border px-5 py-5 text-[11px] text-muted-foreground md:flex-row md:px-10"><span>Rakt Kavach National Blood Grid</span><span>Built for calm, auditable action.</span></footer></div>;
}

function DonorPage() {
  const queryClient = useQueryClient();
  const [showRegister, setShowRegister] = useState(false);
  const [selectedId, setSelectedId] = useState('');
  const summary = useGetDashboardSummary({ role: 'donor' }, { query: { queryKey: getGetDashboardSummaryQueryKey({ role: 'donor' }) } });
  const donors = useListDonors({ limit: 20 }, { query: { queryKey: getListDonorsQueryKey({ limit: 20 }) } });
  const activeId = selectedId || donors.data?.items?.[0]?.id || '';
  const donor = useGetDonor(activeId, { query: { enabled: !!activeId, queryKey: getGetDonorQueryKey(activeId) } });
  const history = useGetDonorHistory(activeId, { query: { enabled: !!activeId, queryKey: getGetDonorHistoryQueryKey(activeId) } });
  const create = useCreateDonor();
  const update = useUpdateDonor();
  const [form, setForm] = useState({ fullName: '', bloodGroup: 'O+', city: '', phoneLast4: '' });
  const submit = (event: FormEvent) => { event.preventDefault(); create.mutate({ data: form as any }, { onSuccess: () => { setShowRegister(false); setForm({ fullName: '', bloodGroup: 'O+', city: '', phoneLast4: '' }); queryClient.invalidateQueries({ queryKey: getListDonorsQueryKey({ limit: 20 }) }); } }); };
  const current = donor.data;
  return <Shell><PageHeader eyebrow="Donor wallet / personal registry" title="Your readiness, carried with you." detail="A verified donor identity for every facility in the network. Your eligibility is always visible before you commit to a donation." action={<button onClick={() => setShowRegister((value) => !value)} className="inline-flex items-center gap-2 rounded-lg bg-primary px-4 py-2.5 text-sm font-bold text-primary-foreground" data-testid="button-register-donor"><UserRound size={16} />Register donor</button>} />
    {showRegister && <SectionCard title="Register a donor identity" eyebrow="New registry record" className="mb-5"><form onSubmit={submit} className="grid gap-3 md:grid-cols-4"><input required minLength={2} value={form.fullName} onChange={(e) => setForm({ ...form, fullName: e.target.value })} placeholder="Full name" className="field" data-testid="input-donor-name" /><select value={form.bloodGroup} onChange={(e) => setForm({ ...form, bloodGroup: e.target.value })} className="field" data-testid="select-donor-blood-group">{bloodGroups.map((group) => <option key={group}>{group}</option>)}</select><input required minLength={2} value={form.city} onChange={(e) => setForm({ ...form, city: e.target.value })} placeholder="City" className="field" data-testid="input-donor-city" /><div className="flex gap-2"><input minLength={4} maxLength={4} value={form.phoneLast4} onChange={(e) => setForm({ ...form, phoneLast4: e.target.value })} placeholder="Phone last 4" className="field min-w-0 flex-1" data-testid="input-donor-phone" /><button disabled={create.isPending} className="rounded-lg bg-primary px-4 text-sm font-bold text-primary-foreground disabled:opacity-50" data-testid="button-submit-donor">{create.isPending ? 'Saving' : 'Save'}</button></div></form>{create.isError && <p className="mt-3 text-xs text-destructive">Registration could not be saved. Please check the details and try again.</p>}</SectionCard>}
    <div className="mb-5">{summary.isLoading ? <LoadingBlock rows={1} /> : summary.isError ? <QueryError /> : <SummaryStrip summary={summary.data} />}</div>
    <div className="grid gap-5 lg:grid-cols-[1.45fr_.8fr]">
      <SectionCard title="Identity wallet" eyebrow="Selected donor profile" action={donors.data?.items?.length ? <select value={activeId} onChange={(e) => setSelectedId(e.target.value)} className="rounded-md border border-border bg-secondary px-2 py-1 text-xs" data-testid="select-donor-profile">{donors.data.items.map((item: any) => <option value={item.id} key={item.id}>{item.donorCode} · {item.fullName || 'Unnamed donor'}</option>)}</select> : null}>
        {donors.isLoading ? <LoadingBlock rows={4} /> : donors.isError ? <QueryError /> : current ? <div className="grid gap-5 md:grid-cols-[1fr_190px]"><div><div className="flex items-center gap-3"><span className="grid size-12 place-items-center rounded-full bg-primary/10 font-display font-bold text-primary">{initials(current.fullName)}</span><div><div className="flex items-center gap-2"><h3 className="font-display text-xl font-bold">{current.fullName || 'Unnamed donor'}</h3>{current.verified && <BadgeCheck size={17} className="text-accent" />}</div><p className="font-mono text-xs text-muted-foreground">{current.donorCode} · {current.city}</p></div></div><div className="mt-7 grid grid-cols-2 gap-4 sm:grid-cols-4"><div><p className="rk-kicker">Blood group</p><p className="mt-1 font-display text-2xl font-bold text-primary">{current.bloodGroup}</p></div><div><p className="rk-kicker">Eligibility</p><Pill tone={statusTone(current.eligibilityStatus)}>{titleCase(current.eligibilityStatus)}</Pill></div><div><p className="rk-kicker">Next eligible</p><p className="mt-1 text-sm font-semibold">{dateLabel(current.nextEligibleAt)}</p></div><div><p className="rk-kicker">Credits</p><p className="mt-1 font-display text-lg font-bold">{current.bloodCredits ?? 0}</p></div></div><div className="mt-7 flex flex-wrap gap-2"><button onClick={() => update.mutate({ donorId: current.id, data: { eligibilityStatus: 'eligible' } as any }, { onSuccess: () => { queryClient.invalidateQueries({ queryKey: getGetDonorQueryKey(current.id) }); queryClient.invalidateQueries({ queryKey: getListDonorsQueryKey({ limit: 20 }) }); } })} className="inline-flex items-center gap-2 rounded-lg border border-border px-3 py-2 text-xs font-bold hover:bg-secondary" data-testid="button-confirm-eligibility"><Check size={14} />Mark ready</button><Link href={`/verify/${current.donorCode}`} className="inline-flex items-center gap-2 rounded-lg border border-border px-3 py-2 text-xs font-bold hover:bg-secondary" data-testid="link-donor-qr"><QrCode size={14} />Open QR identity</Link></div></div><div className="flex min-h-[180px] flex-col items-center justify-center rounded-xl border border-dashed border-primary/25 bg-primary/[.03]"><QrCode size={64} strokeWidth={1.2} className="text-primary" /><p className="mt-3 font-mono text-[10px] uppercase tracking-[.16em] text-muted-foreground">Identity pass</p><p className="mt-1 text-xs font-semibold">{current.donorCode}</p></div></div> : <EmptyState icon={UserRound} title="No donor identity selected" detail="Register a donor or wait for the connected registry to return a profile." />}
      </SectionCard>
      <SectionCard title="Donation history" eyebrow="Verified contributions"><div className="space-y-3">{history.isLoading ? <LoadingBlock rows={3} /> : history.isError ? <QueryError /> : history.data?.items?.length ? history.data.items.map((item: any) => <div key={item.id} className="flex items-center gap-3 border-b border-border pb-3 last:border-0 last:pb-0" data-testid={`history-row-${item.id}`}><span className="grid size-8 place-items-center rounded-lg bg-accent/10 text-accent"><HeartPulse size={15} /></span><div className="min-w-0 flex-1"><p className="truncate text-xs font-bold">{item.facilityName}</p><p className="mt-1 text-[11px] text-muted-foreground">{dateLabel(item.donatedAt)} · {item.units} unit{item.units === 1 ? '' : 's'}</p></div><span className="font-mono text-xs text-muted-foreground">{item.bloodGroup || current?.bloodGroup}</span></div>) : <EmptyState icon={HeartPulse} title="No donations recorded" detail="Completed donations verified by a connected facility will appear here." />}</div></SectionCard>
    </div>
  </Shell>;
}

function HospitalPage() {
  const queryClient = useQueryClient();
  const summary = useGetDashboardSummary({ role: 'hospital' }, { query: { queryKey: getGetDashboardSummaryQueryKey({ role: 'hospital' }) } });
  const requests = useListBloodRequests({}, { query: { queryKey: getListBloodRequestsQueryKey({}) } });
  const inventory = useListBloodUnits({ status: 'available', limit: 20 }, { query: { queryKey: getListBloodUnitsQueryKey({ status: 'available', limit: 20 }) } });
  const emergencies = useListEmergencies({ status: 'active' }, { query: { queryKey: getListEmergenciesQueryKey({ status: 'active' }) } });
  const createRequest = useCreateBloodRequest();
  const createEmergency = useCreateEmergency();
  const updateRequest = useUpdateBloodRequestStatus();
  const [requestOpen, setRequestOpen] = useState(false);
  const [emergencyOpen, setEmergencyOpen] = useState(false);
  const [requestForm, setRequestForm] = useState({ bloodGroup: 'O+', component: 'red-cells', units: 1, urgency: 'urgent', facilityId: '', patientReference: '', neededBy: '' });
  const [emergencyForm, setEmergencyForm] = useState({ bloodGroup: 'O+', units: 1, urgency: 'critical', city: '', hospitalName: '', coordinatorPhoneLast4: '' });
  const submitRequest = (event: FormEvent) => { event.preventDefault(); createRequest.mutate({ data: { ...requestForm, units: Number(requestForm.units) } as any }, { onSuccess: () => { setRequestOpen(false); queryClient.invalidateQueries({ queryKey: getListBloodRequestsQueryKey({}) }); } }); };
  const submitEmergency = (event: FormEvent) => { event.preventDefault(); createEmergency.mutate({ data: { ...emergencyForm, units: Number(emergencyForm.units) } as any }, { onSuccess: () => { setEmergencyOpen(false); queryClient.invalidateQueries({ queryKey: getListEmergenciesQueryKey({ status: 'active' }) }); } }); };
  return <Shell><PageHeader eyebrow="Hospital command center" title="Move from need to match." detail="Track open requests, live stock and high-priority response cases from one accountable workspace." action={<div className="flex gap-2"><button onClick={() => setRequestOpen(true)} className="inline-flex items-center gap-2 rounded-lg border border-border bg-card px-3 py-2.5 text-xs font-bold" data-testid="button-new-request"><ClipboardList size={15} />New request</button><button onClick={() => setEmergencyOpen(true)} className="inline-flex items-center gap-2 rounded-lg bg-primary px-3 py-2.5 text-xs font-bold text-primary-foreground" data-testid="button-new-emergency"><Siren size={15} />Start SOS</button></div>} />
    {(requestOpen || emergencyOpen) && <SectionCard title={requestOpen ? 'Create blood request' : 'Open emergency response'} eyebrow="Submit to national grid" className="mb-5">{requestOpen ? <form onSubmit={submitRequest} className="grid gap-3 md:grid-cols-3"><select className="field" value={requestForm.bloodGroup} onChange={(e) => setRequestForm({ ...requestForm, bloodGroup: e.target.value })} data-testid="select-request-group">{bloodGroups.map((group) => <option key={group}>{group}</option>)}</select><input className="field" value={requestForm.component} onChange={(e) => setRequestForm({ ...requestForm, component: e.target.value })} placeholder="Component" required data-testid="input-request-component" /><input className="field" type="number" min="1" value={requestForm.units} onChange={(e) => setRequestForm({ ...requestForm, units: Number(e.target.value) })} placeholder="Units" required data-testid="input-request-units" /><select className="field" value={requestForm.urgency} onChange={(e) => setRequestForm({ ...requestForm, urgency: e.target.value })} data-testid="select-request-urgency"><option value="routine">Routine</option><option value="urgent">Urgent</option><option value="critical">Critical</option></select><input className="field" value={requestForm.facilityId} onChange={(e) => setRequestForm({ ...requestForm, facilityId: e.target.value })} placeholder="Facility ID" required data-testid="input-request-facility" /><input className="field" value={requestForm.patientReference} onChange={(e) => setRequestForm({ ...requestForm, patientReference: e.target.value })} placeholder="Patient reference (optional)" data-testid="input-request-patient" /><div className="flex gap-2 md:col-span-3"><button className="rounded-lg bg-primary px-4 py-2 text-xs font-bold text-primary-foreground" disabled={createRequest.isPending} data-testid="button-submit-request">Submit request</button><button type="button" onClick={() => setRequestOpen(false)} className="rounded-lg border border-border px-4 py-2 text-xs font-bold" data-testid="button-cancel-request">Cancel</button></div></form> : <form onSubmit={submitEmergency} className="grid gap-3 md:grid-cols-3"><select className="field" value={emergencyForm.bloodGroup} onChange={(e) => setEmergencyForm({ ...emergencyForm, bloodGroup: e.target.value })} data-testid="select-emergency-group">{bloodGroups.map((group) => <option key={group}>{group}</option>)}</select><input className="field" type="number" min="1" value={emergencyForm.units} onChange={(e) => setEmergencyForm({ ...emergencyForm, units: Number(e.target.value) })} placeholder="Units" data-testid="input-emergency-units" /><select className="field" value={emergencyForm.urgency} onChange={(e) => setEmergencyForm({ ...emergencyForm, urgency: e.target.value })} data-testid="select-emergency-urgency"><option value="critical">Critical</option><option value="urgent">Urgent</option></select><input className="field" value={emergencyForm.city} onChange={(e) => setEmergencyForm({ ...emergencyForm, city: e.target.value })} placeholder="City" required data-testid="input-emergency-city" /><input className="field" value={emergencyForm.hospitalName} onChange={(e) => setEmergencyForm({ ...emergencyForm, hospitalName: e.target.value })} placeholder="Hospital name" data-testid="input-emergency-hospital" /><input className="field" minLength={4} maxLength={4} value={emergencyForm.coordinatorPhoneLast4} onChange={(e) => setEmergencyForm({ ...emergencyForm, coordinatorPhoneLast4: e.target.value })} placeholder="Coordinator phone last 4" data-testid="input-emergency-phone" /><div className="flex gap-2 md:col-span-3"><button className="rounded-lg bg-primary px-4 py-2 text-xs font-bold text-primary-foreground" disabled={createEmergency.isPending} data-testid="button-submit-emergency">Broadcast SOS</button><button type="button" onClick={() => setEmergencyOpen(false)} className="rounded-lg border border-border px-4 py-2 text-xs font-bold" data-testid="button-cancel-emergency">Cancel</button></div></form>}</SectionCard>}
    <div className="mb-5">{summary.isLoading ? <LoadingBlock rows={1} /> : <SummaryStrip summary={summary.data} />}</div><div className="grid gap-5 xl:grid-cols-[1.25fr_.75fr]"><SectionCard title="Requests in motion" eyebrow="Hospital queue" action={<Link href="/sos" className="text-xs font-bold text-primary" data-testid="link-hospital-sos">View response desk</Link>}>{requests.isLoading ? <LoadingBlock /> : requests.isError ? <QueryError /> : requests.data?.items?.length ? <div className="space-y-2">{requests.data.items.map((request: any) => <div key={request.id} className="flex flex-col gap-3 rounded-lg border border-border p-3 sm:flex-row sm:items-center" data-testid={`request-row-${request.id}`}><span className={`grid size-9 shrink-0 place-items-center rounded-lg ${request.urgency === 'critical' ? 'bg-primary/10 text-primary' : 'bg-secondary text-muted-foreground'}`}><PackageCheck size={17} /></span><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><p className="font-mono text-xs font-bold">{request.requestCode}</p><Pill tone={statusTone(request.urgency)}>{request.urgency}</Pill></div><p className="mt-1 text-xs text-muted-foreground">{request.bloodGroup} · {request.component} · {request.units} units · {request.facilityName || request.facilityId}</p></div><div className="flex items-center gap-2"><Pill tone={statusTone(request.status)}>{titleCase(request.status)}</Pill>{request.status === 'open' && <button onClick={() => updateRequest.mutate({ requestId: request.id, data: { status: 'matched' } as any }, { onSuccess: () => queryClient.invalidateQueries({ queryKey: getListBloodRequestsQueryKey({}) }) })} className="rounded-md border border-border px-2 py-1 text-[11px] font-bold" data-testid={`button-match-request-${request.id}`}>Match</button>}</div></div>)}</div> : <EmptyState icon={ClipboardList} title="No requests in queue" detail="New facility requests will appear here as soon as the grid receives them." />}</SectionCard><div className="space-y-5"><SectionCard title="Active SOS cases" eyebrow="Immediate action"><div className="space-y-2">{emergencies.isLoading ? <LoadingBlock rows={2} /> : emergencies.data?.items?.length ? emergencies.data.items.slice(0, 4).map((item: any) => <div key={item.id} className="rounded-lg border border-primary/20 bg-primary/[.03] p-3" data-testid={`emergency-row-${item.id}`}><div className="flex items-center justify-between"><span className="font-mono text-xs font-bold text-primary">{item.caseCode}</span><Pill tone={statusTone(item.urgency)}>{item.urgency}</Pill></div><p className="mt-2 text-sm font-semibold">{item.bloodGroup} · {item.units} units · {item.city}</p><p className="mt-1 text-xs text-muted-foreground">{item.hospitalName || 'Hospital not supplied'} · ETA {item.responseEtaMinutes ?? 'pending'} min</p></div>) : <EmptyState icon={Siren} title="No active cases" detail="The response desk has no live emergency cases at this moment." />}</div></SectionCard><SectionCard title="Available now" eyebrow="Connected inventory"><div className="space-y-2">{inventory.isLoading ? <LoadingBlock rows={3} /> : inventory.data?.items?.length ? inventory.data.items.slice(0, 5).map((unit: any) => <div className="flex items-center gap-3 border-b border-border pb-2 last:border-0" key={unit.id} data-testid={`inventory-match-${unit.id}`}><span className="font-display text-lg font-bold text-primary">{unit.bloodGroup}</span><div className="min-w-0 flex-1"><p className="truncate text-xs font-semibold">{unit.component}</p><p className="text-[11px] text-muted-foreground">{unit.facilityName || unit.facilityId}</p></div><span className="text-[11px] text-muted-foreground">{dateLabel(unit.expiresAt)}</span></div>) : <EmptyState icon={PackageCheck} title="No available units" detail="Live verified inventory will appear when facilities publish stock." />}</div></SectionCard></div></div>
  </Shell>;
}

function BloodBankPage() {
  const queryClient = useQueryClient();
  const units = useListBloodUnits({ limit: 50 }, { query: { queryKey: getListBloodUnitsQueryKey({ limit: 50 }) } });
  const facilities = useListFacilities({ type: 'blood-bank' }, { query: { queryKey: getListFacilitiesQueryKey({ type: 'blood-bank' }) } });
  const timeline = useGetBloodUnitTimeline({}, { query: { queryKey: getGetBloodUnitTimelineQueryKey({}) } });
  const create = useCreateBloodUnit();
  const update = useUpdateBloodUnit();
  const [open, setOpen] = useState(false);
  const [form, setForm] = useState({ unitCode: '', bloodGroup: 'O+', component: 'red-cells', facilityId: '', collectedAt: '', expiresAt: '', qrToken: '' });
  const submit = (event: FormEvent) => { event.preventDefault(); create.mutate({ data: form as any }, { onSuccess: () => { setOpen(false); queryClient.invalidateQueries({ queryKey: getListBloodUnitsQueryKey({ limit: 50 }) }); } }); };
  return <Shell><PageHeader eyebrow="Blood bank / inventory operations" title="Know every unit by its next move." detail="Publish verified stock, quarantine exceptions and follow a unit's chain of custody without losing the clock." action={<button onClick={() => setOpen(!open)} className="inline-flex items-center gap-2 rounded-lg bg-primary px-4 py-2.5 text-xs font-bold text-primary-foreground" data-testid="button-add-unit"><PackageCheck size={16} />Add verified unit</button>} />{open && <SectionCard title="Add verified blood unit" eyebrow="Inventory intake" className="mb-5"><form onSubmit={submit} className="grid gap-3 md:grid-cols-3"><input className="field" required minLength={4} value={form.unitCode} onChange={(e) => setForm({ ...form, unitCode: e.target.value })} placeholder="Unit code" data-testid="input-unit-code" /><select className="field" value={form.bloodGroup} onChange={(e) => setForm({ ...form, bloodGroup: e.target.value })} data-testid="select-unit-group">{bloodGroups.map((group) => <option key={group}>{group}</option>)}</select><input className="field" required value={form.component} onChange={(e) => setForm({ ...form, component: e.target.value })} placeholder="Component" data-testid="input-unit-component" /><select className="field" value={form.facilityId} onChange={(e) => setForm({ ...form, facilityId: e.target.value })} required data-testid="select-unit-facility"><option value="">Select facility</option>{facilities.data?.items?.map((facility: any) => <option key={facility.id} value={facility.id}>{facility.name}</option>)}</select><input className="field" type="datetime-local" required value={form.collectedAt} onChange={(e) => setForm({ ...form, collectedAt: e.target.value })} data-testid="input-unit-collected" /><input className="field" type="datetime-local" required value={form.expiresAt} onChange={(e) => setForm({ ...form, expiresAt: e.target.value })} data-testid="input-unit-expires" /><input className="field md:col-span-2" minLength={8} value={form.qrToken} onChange={(e) => setForm({ ...form, qrToken: e.target.value })} placeholder="QR token (optional)" data-testid="input-unit-token" /><div className="flex items-center gap-2"><button className="rounded-lg bg-primary px-4 py-2 text-xs font-bold text-primary-foreground" disabled={create.isPending} data-testid="button-submit-unit">Publish unit</button><button type="button" onClick={() => setOpen(false)} className="rounded-lg border border-border px-4 py-2 text-xs font-bold" data-testid="button-cancel-unit">Cancel</button></div></form></SectionCard>}<div className="grid gap-5 xl:grid-cols-[1.35fr_.65fr]"><SectionCard title="Live inventory" eyebrow={`${units.data?.total ?? 0} units visible`} action={<button className="rounded-md border border-border p-2" onClick={() => units.refetch()} aria-label="Refresh inventory" data-testid="button-refresh-inventory"><RefreshCw size={14} /></button>}>{units.isLoading ? <LoadingBlock rows={5} /> : units.isError ? <QueryError /> : units.data?.items?.length ? <div className="overflow-x-auto"><table className="data-table"><thead><tr><th>Unit</th><th>Group / component</th><th>Facility</th><th>Expiry</th><th>Status</th><th>Action</th></tr></thead><tbody>{units.data.items.map((unit: any) => <tr key={unit.id} data-testid={`row-unit-${unit.id}`}><td><span className="font-mono text-xs font-bold">{unit.unitCode}</span><span className="block text-[10px] text-muted-foreground">{unit.verified ? 'Verified' : 'Pending verification'}</span></td><td><span className="font-semibold">{unit.bloodGroup}</span><span className="ml-2 text-xs text-muted-foreground">{unit.component}</span></td><td>{unit.facilityName || unit.facilityId}</td><td>{dateLabel(unit.expiresAt)}</td><td><Pill tone={statusTone(unit.status)}>{titleCase(unit.status)}</Pill></td><td><button onClick={() => update.mutate({ unitId: unit.id, data: { status: unit.status === 'available' ? 'quarantined' : 'available' } as any }, { onSuccess: () => queryClient.invalidateQueries({ queryKey: getListBloodUnitsQueryKey({ limit: 50 }) }) })} className="text-[11px] font-bold text-primary underline" data-testid={`button-toggle-unit-${unit.id}`}>{unit.status === 'available' ? 'Quarantine' : 'Release'}</button></td></tr>)}</tbody></table></div> : <EmptyState icon={Database} title="Inventory is clear" detail="Verified blood units published by your connected facilities will appear here." />}</SectionCard><SectionCard title="Unit timeline" eyebrow="Recent custody events"><div className="space-y-4">{timeline.isLoading ? <LoadingBlock rows={4} /> : timeline.data?.items?.length ? timeline.data.items.map((event: any) => <div key={event.id} className="relative flex gap-3 pl-1" data-testid={`timeline-event-${event.id}`}><span className="mt-1 size-2 shrink-0 rounded-full bg-primary ring-4 ring-primary/10" /><div><p className="text-xs font-bold">{titleCase(event.eventType)} · {event.unitCode}</p><p className="mt-1 text-[11px] text-muted-foreground">{event.detail || event.facilityName || 'Network event'} · {dateLabel(event.occurredAt)} {timeLabel(event.occurredAt)}</p></div></div>) : <EmptyState icon={Activity} title="No timeline events" detail="Chain-of-custody events will populate as units move through the network." />}</div></SectionCard></div></Shell>;
}

function LabPage() {
  const [token, setToken] = useState('');
  const verification = useVerifyQrPass(token, { query: { enabled: !!token, queryKey: getVerifyQrPassQueryKey(token) } });
  const units = useListBloodUnits({ limit: 20 }, { query: { queryKey: getListBloodUnitsQueryKey({ limit: 20 }) } });
  return <Shell><PageHeader eyebrow="Laboratory / trust layer" title="Verify before the unit moves." detail="Review QR passes at the point of testing and keep a visible chain between lab confirmation and facility release." action={<Link href="/verify/scan" className="inline-flex items-center gap-2 rounded-lg bg-primary px-4 py-2.5 text-xs font-bold text-primary-foreground" data-testid="link-open-scanner"><QrCode size={16} />Open QR verifier</Link>} /><div className="grid gap-5 lg:grid-cols-[.85fr_1.15fr]"><SectionCard title="QR pass review" eyebrow="Scan or paste a token"><form onSubmit={(event) => { event.preventDefault(); verification.refetch(); }} className="flex gap-2"><input required value={token} onChange={(e) => setToken(e.target.value)} className="field flex-1" placeholder="Paste QR token" data-testid="input-lab-token" /><button className="rounded-lg bg-primary px-4 text-xs font-bold text-primary-foreground" data-testid="button-verify-token">Verify</button></form>{verification.isLoading && <div className="mt-5"><LoadingBlock rows={2} /></div>}{verification.isError && <div className="mt-5"><QueryError message="This pass could not be verified." /></div>}{verification.data && <div className={`mt-5 rounded-xl border p-4 ${verification.data.valid ? 'border-accent/30 bg-accent/5' : 'border-primary/25 bg-primary/5'}`} data-testid="verification-result"><div className="flex items-center gap-3"><span className={`grid size-10 place-items-center rounded-full ${verification.data.valid ? 'bg-accent text-accent-foreground' : 'bg-primary text-primary-foreground'}`}>{verification.data.valid ? <Check size={20} /> : <X size={20} />}</span><div><p className="font-display font-bold">{verification.data.valid ? 'Pass verified' : 'Pass rejected'}</p><p className="text-xs text-muted-foreground">{verification.data.displayLabel || verification.data.reason || 'No additional label supplied'}</p></div></div><div className="mt-4 grid grid-cols-2 gap-3 text-xs"><div><span className="rk-kicker">Type</span><p className="mt-1 font-semibold">{titleCase(verification.data.verificationType)}</p></div><div><span className="rk-kicker">Status</span><p className="mt-1 font-semibold">{verification.data.status || '—'}</p></div></div></div>}</SectionCard><SectionCard title="Units awaiting review" eyebrow="Connected inventory"><div className="space-y-2">{units.isLoading ? <LoadingBlock rows={4} /> : units.data?.items?.length ? units.data.items.slice(0, 8).map((unit: any) => <div className="flex items-center gap-3 rounded-lg border border-border p-3" key={unit.id} data-testid={`lab-unit-${unit.id}`}><span className="grid size-8 place-items-center rounded-lg bg-secondary font-mono text-[10px] font-bold text-primary">{unit.bloodGroup}</span><div className="min-w-0 flex-1"><p className="truncate text-xs font-bold">{unit.unitCode}</p><p className="mt-1 text-[11px] text-muted-foreground">{unit.component} · {unit.facilityName || unit.facilityId}</p></div><Pill tone={unit.verified ? 'status status-good' : 'status status-watch'}>{unit.verified ? 'Verified' : 'Review'}</Pill></div>) : <EmptyState icon={FileCheck2} title="No units awaiting review" detail="Newly collected units from connected blood banks will appear here." />}</div></SectionCard></div></Shell>;
}

function AuthorityPage() {
  const summary = useGetDashboardSummary({ role: 'authority' }, { query: { queryKey: getGetDashboardSummaryQueryKey({ role: 'authority' }) } });
  const trends = useGetEmergencyTrends({ period: '7d' }, { query: { queryKey: getGetEmergencyTrendsQueryKey({ period: '7d' }) } });
  const facilities = useListFacilities({}, { query: { queryKey: getListFacilitiesQueryKey({}) } });
  const logs = useGetAuditLogs({ limit: 10 }, { query: { queryKey: getGetAuditLogsQueryKey({ limit: 10 }) } });
  const guardian = useGetAiGuardian({ query: { queryKey: getGetAiGuardianQueryKey() } });
  return <Shell><PageHeader eyebrow="Authority / national oversight" title="See the grid, not the noise." detail="A nationwide view of readiness, emergency pressure and facility accountability. Built for decisions that need a timestamp." action={<button className="inline-flex items-center gap-2 rounded-lg border border-border bg-card px-4 py-2.5 text-xs font-bold" onClick={() => summary.refetch()} data-testid="button-refresh-authority"><RefreshCw size={15} />Refresh snapshot</button>} /><div className="mb-5">{summary.isLoading ? <LoadingBlock rows={1} /> : <SummaryStrip summary={summary.data} />}</div><div className="grid gap-5 xl:grid-cols-[1.2fr_.8fr]"><SectionCard title="Emergency pressure · 7 days" eyebrow="Trendline"><div className="flex h-52 items-end gap-2 border-b border-l border-border px-3 pb-0 pt-5">{trends.isLoading ? <LoadingBlock rows={3} /> : trends.data?.points?.length ? trends.data.points.map((point: any) => <div key={point.label} className="flex h-full flex-1 flex-col justify-end gap-1" data-testid={`trend-point-${point.label}`}><div className="mx-auto w-full max-w-8 rounded-t bg-primary/75" style={{ height: `${Math.max(8, point.emergencies * 12)}%` }} /><div className="mx-auto w-full max-w-8 rounded-t bg-accent/70" style={{ height: `${Math.max(6, point.fulfilled * 10)}%` }} /><span className="mt-2 text-center font-mono text-[9px] text-muted-foreground">{point.label}</span></div>) : <EmptyState icon={Activity} title="Trend data not available" detail="The grid will display trend pressure after emergency events are recorded." />}</div><div className="mt-4 flex gap-4 text-[11px] text-muted-foreground"><span className="flex items-center gap-1.5"><i className="size-2 rounded-full bg-primary" />Emergencies</span><span className="flex items-center gap-1.5"><i className="size-2 rounded-full bg-accent" />Fulfilled</span></div></SectionCard><SectionCard title="AI Guardian" eyebrow="Risk signals"><div className="flex items-start gap-4"><div className={`grid size-12 shrink-0 place-items-center rounded-xl ${guardian.data?.status === 'attention' ? 'bg-primary/10 text-primary' : 'bg-accent/10 text-accent'}`}><ShieldCheck size={24} /></div><div><div className="flex items-center gap-2"><p className="font-display font-bold">{titleCase(guardian.data?.status || 'monitoring')}</p><Pill tone={statusTone(guardian.data?.status)}>{guardian.data?.signals?.length ?? 0} signals</Pill></div><p className="mt-1 text-xs text-muted-foreground">Generated {dateLabel(guardian.data?.generatedAt)}</p></div></div><div className="mt-5 space-y-2">{guardian.isLoading ? <LoadingBlock rows={2} /> : guardian.data?.signals?.length ? guardian.data.signals.slice(0, 4).map((signal: any) => <div key={signal.id} className="rounded-lg border border-border p-3" data-testid={`guardian-signal-${signal.id}`}><div className="flex items-center justify-between gap-2"><p className="text-xs font-bold">{signal.title}</p><Pill tone={statusTone(signal.severity)}>{signal.severity}</Pill></div><p className="mt-1 text-[11px] leading-5 text-muted-foreground">{signal.description}</p></div>) : <EmptyState icon={ShieldCheck} title="No active signals" detail="Guardian is monitoring the network for anomalies." />}</div></SectionCard></div><div className="mt-5 grid gap-5 xl:grid-cols-[1fr_1fr]"><SectionCard title="Facility network" eyebrow={`${facilities.data?.total ?? 0} connected facilities`}><div className="grid gap-2 md:grid-cols-2">{facilities.isLoading ? <LoadingBlock rows={4} /> : facilities.data?.items?.length ? facilities.data.items.slice(0, 8).map((facility: any) => <div className="flex items-center gap-3 rounded-lg border border-border p-3" key={facility.id} data-testid={`facility-row-${facility.id}`}><span className="grid size-9 place-items-center rounded-lg bg-secondary text-primary"><Building2 size={16} /></span><div className="min-w-0 flex-1"><p className="truncate text-xs font-bold">{facility.name}</p><p className="mt-1 text-[11px] text-muted-foreground">{titleCase(facility.type)} · {facility.city}, {facility.state}</p></div><span className="font-mono text-[10px] text-muted-foreground">{facility.liveUnits ?? 0} units</span></div>) : <EmptyState icon={Building2} title="No facilities returned" detail="Connected facilities will appear when the registry responds." />}</div></SectionCard><SectionCard title="Audit activity" eyebrow="Immutable network record"><div className="space-y-3">{logs.isLoading ? <LoadingBlock rows={5} /> : logs.data?.items?.length ? logs.data.items.map((log: any) => <div className="flex gap-3" key={log.id} data-testid={`audit-row-${log.id}`}><span className="mt-1 grid size-6 place-items-center rounded-md bg-secondary"><LockKeyhole size={12} /></span><div className="min-w-0 flex-1"><p className="text-xs font-semibold">{titleCase(log.action)}</p><p className="mt-1 text-[11px] text-muted-foreground">{titleCase(log.actorType)} · {log.resourceType || 'network'} · {timeLabel(log.occurredAt)}</p></div></div>) : <EmptyState icon={ClipboardList} title="Audit log is empty" detail="Recorded actions will appear here with actor and resource context." />}</div></SectionCard></div></Shell>;
}

function FounderPage() {
  const summary = useGetDashboardSummary({ role: 'founder' }, { query: { queryKey: getGetDashboardSummaryQueryKey({ role: 'founder' }) } });
  const integrations = useGetIntegrationStatus({ query: { queryKey: getGetIntegrationStatusQueryKey() } });
  const health = useHealthCheck();
  return <Shell><PageHeader eyebrow="Founder command center" title="Keep the network worthy of trust." detail="Platform health, connector readiness and the operational pulse behind every blood movement." /><div className="mb-5">{summary.isLoading ? <LoadingBlock rows={1} /> : <SummaryStrip summary={summary.data} />}</div><div className="grid gap-5 lg:grid-cols-[.8fr_1.2fr]"><SectionCard title="Connector health" eyebrow="External systems"><div className="space-y-3">{integrations.isLoading ? <LoadingBlock rows={5} /> : integrations.data?.items?.length ? integrations.data.items.map((item: any) => <div className="flex items-center gap-3 rounded-lg border border-border p-3" key={item.key} data-testid={`integration-row-${item.key}`}><span className={`grid size-9 place-items-center rounded-lg ${item.status === 'configured' ? 'bg-accent/10 text-accent' : item.status === 'unavailable' ? 'bg-primary/10 text-primary' : 'bg-secondary text-muted-foreground'}`}><Link2 size={16} /></span><div className="min-w-0 flex-1"><p className="text-xs font-bold">{item.name}</p><p className="mt-1 truncate text-[11px] text-muted-foreground">{item.detail || 'No connector detail supplied'}</p></div><Pill tone={statusTone(item.status)}>{titleCase(item.status)}</Pill></div>) : <EmptyState icon={Link2} title="No connectors registered" detail="Integration status will appear as platform connectors are configured." />}</div></SectionCard><SectionCard title="Platform heartbeat" eyebrow="Runtime posture"><div className="rounded-xl bg-sidebar p-5 text-sidebar-foreground"><div className="flex items-center justify-between"><div><p className="rk-kicker text-sidebar-foreground/50">API service</p><p className="mt-2 font-display text-2xl font-bold">{health.data?.status || (health.isLoading ? 'Checking' : 'Unavailable')}</p></div><span className="grid size-12 place-items-center rounded-xl bg-sidebar-primary/15 text-sidebar-primary"><Radio size={23} /></span></div><div className="mt-7 grid grid-cols-2 gap-4 border-t border-sidebar-border pt-4"><div><p className="rk-kicker text-sidebar-foreground/50">Service</p><p className="mt-1 text-xs font-semibold">{health.data?.service || '—'}</p></div><div><p className="rk-kicker text-sidebar-foreground/50">Last check</p><p className="mt-1 text-xs font-semibold">{timeLabel(health.data?.timestamp)}</p></div></div></div><div className="mt-4 grid gap-2 sm:grid-cols-3"><div className="rounded-lg border border-border p-3"><p className="rk-kicker">Auditability</p><p className="mt-2 text-sm font-bold text-accent">Enabled</p></div><div className="rounded-lg border border-border p-3"><p className="rk-kicker">PWA shell</p><p className="mt-2 text-sm font-bold text-accent">Installable</p></div><div className="rounded-lg border border-border p-3"><p className="rk-kicker">Language layer</p><p className="mt-2 text-sm font-bold text-muted-foreground">Ready</p></div></div></SectionCard></div></Shell>;
}

function SosPage() {
  const queryClient = useQueryClient();
  const cases = useListEmergencies({}, { query: { queryKey: getListEmergenciesQueryKey({}) } });
  const create = useCreateEmergency();
  const update = useUpdateEmergencyStatus();
  const [open, setOpen] = useState(false);
  const [form, setForm] = useState({ bloodGroup: 'O-', units: 2, urgency: 'critical', city: '', hospitalName: '', coordinatorPhoneLast4: '' });
  const submit = (event: FormEvent) => { event.preventDefault(); create.mutate({ data: { ...form, units: Number(form.units) } as any }, { onSuccess: () => { setOpen(false); queryClient.invalidateQueries({ queryKey: getListEmergenciesQueryKey({}) }); } }); };
  return <Shell><PageHeader eyebrow="SOS / emergency response" title="The shortest path to a match." detail="Broadcast a verified need to the grid, then keep the response state visible to every coordinator." action={<button onClick={() => setOpen(!open)} className="inline-flex items-center gap-2 rounded-lg bg-primary px-4 py-2.5 text-xs font-bold text-primary-foreground" data-testid="button-create-sos"><Siren size={16} />Create emergency case</button>} />{open && <SectionCard title="Create emergency case" eyebrow="Broadcast to response network" className="mb-5"><form onSubmit={submit} className="grid gap-3 md:grid-cols-3"><select className="field" value={form.bloodGroup} onChange={(e) => setForm({ ...form, bloodGroup: e.target.value })} data-testid="select-sos-group">{bloodGroups.map((group) => <option key={group}>{group}</option>)}</select><input className="field" type="number" min="1" required value={form.units} onChange={(e) => setForm({ ...form, units: Number(e.target.value) })} placeholder="Units needed" data-testid="input-sos-units" /><select className="field" value={form.urgency} onChange={(e) => setForm({ ...form, urgency: e.target.value })} data-testid="select-sos-urgency"><option value="critical">Critical</option><option value="urgent">Urgent</option></select><input className="field" required value={form.city} onChange={(e) => setForm({ ...form, city: e.target.value })} placeholder="City" data-testid="input-sos-city" /><input className="field" value={form.hospitalName} onChange={(e) => setForm({ ...form, hospitalName: e.target.value })} placeholder="Hospital name" data-testid="input-sos-hospital" /><input className="field" minLength={4} maxLength={4} value={form.coordinatorPhoneLast4} onChange={(e) => setForm({ ...form, coordinatorPhoneLast4: e.target.value })} placeholder="Coordinator phone last 4" data-testid="input-sos-phone" /><div className="flex gap-2 md:col-span-3"><button className="rounded-lg bg-primary px-4 py-2 text-xs font-bold text-primary-foreground" disabled={create.isPending} data-testid="button-submit-sos">Broadcast emergency</button><button type="button" onClick={() => setOpen(false)} className="rounded-lg border border-border px-4 py-2 text-xs font-bold" data-testid="button-cancel-sos">Cancel</button></div></form></SectionCard>}<SectionCard title="Response board" eyebrow={`${cases.data?.total ?? 0} cases in the grid`} action={<button className="rounded-md border border-border p-2" onClick={() => cases.refetch()} aria-label="Refresh cases" data-testid="button-refresh-sos"><RefreshCw size={14} /></button>}>{cases.isLoading ? <LoadingBlock rows={5} /> : cases.isError ? <QueryError /> : cases.data?.items?.length ? <div className="grid gap-3 lg:grid-cols-2">{cases.data.items.map((item: any) => <div className={`rounded-xl border p-4 ${item.status === 'active' ? 'border-primary/30 bg-primary/[.03]' : 'border-border'}`} key={item.id} data-testid={`sos-case-${item.id}`}><div className="flex items-start justify-between gap-2"><div><p className="font-mono text-xs font-bold text-primary">{item.caseCode}</p><p className="mt-2 font-display text-lg font-bold">{item.bloodGroup} <span className="text-muted-foreground">×</span> {item.units} units</p></div><Pill tone={statusTone(item.status)}>{titleCase(item.status)}</Pill></div><div className="mt-4 grid grid-cols-2 gap-3 text-xs"><div><span className="rk-kicker">Location</span><p className="mt-1 font-semibold">{item.city}</p></div><div><span className="rk-kicker">Response ETA</span><p className="mt-1 font-semibold">{item.responseEtaMinutes ?? 'Pending'}{item.responseEtaMinutes ? ' min' : ''}</p></div><div><span className="rk-kicker">Hospital</span><p className="mt-1 truncate font-semibold">{item.hospitalName || 'Not supplied'}</p></div><div><span className="rk-kicker">Opened</span><p className="mt-1 font-semibold">{dateLabel(item.createdAt)}</p></div></div>{item.status !== 'resolved' && item.status !== 'cancelled' && <div className="mt-4 flex flex-wrap gap-2">{(['acknowledged', 'dispatched', 'resolved'] as const).map((status) => <button key={status} onClick={() => update.mutate({ emergencyId: item.id, data: { status, responseEtaMinutes: status === 'resolved' ? 0 : item.responseEtaMinutes } as any }, { onSuccess: () => queryClient.invalidateQueries({ queryKey: getListEmergenciesQueryKey({}) }) })} className="rounded-md border border-border px-2.5 py-1.5 text-[11px] font-bold hover:bg-secondary" data-testid={`button-sos-${status}-${item.id}`}>{titleCase(status)}</button>)}</div>}</div>)}</div> : <EmptyState icon={Siren} title="No emergency cases" detail="When a hospital or coordinator broadcasts an SOS, the live response board will begin tracking it here." />}</SectionCard></Shell>;
}

function VerifyPage() {
  const params = useParams<{ token?: string }>();
  const [token, setToken] = useState(params.token === 'scan' ? '' : params.token || '');
  const verify = useVerifyQrPass(token, { query: { enabled: !!token, queryKey: getVerifyQrPassQueryKey(token) } });
  return <Shell><div className="mx-auto max-w-2xl py-8 md:py-16"><PageHeader eyebrow="Trust layer / QR verification" title="Verify a pass in seconds." detail="Confirm donor identity or blood-unit provenance before a handoff. A valid pass is always tied to a live grid record." /><SectionCard title="Verification desk" eyebrow="Secure lookup"><form onSubmit={(event) => { event.preventDefault(); verify.refetch(); }} className="flex flex-col gap-2 sm:flex-row"><input className="field flex-1" required value={token} onChange={(e) => setToken(e.target.value)} placeholder="Enter or scan token" data-testid="input-verify-token" /><button className="rounded-lg bg-primary px-5 py-2.5 text-sm font-bold text-primary-foreground" data-testid="button-submit-verification">Verify pass</button></form>{verify.isLoading && <div className="mt-6"><LoadingBlock rows={3} /></div>}{verify.isError && <div className="mt-6"><QueryError message="No verified record matched this token." /></div>}{verify.data && <div className={`mt-6 rounded-xl border p-5 ${verify.data.valid ? 'border-accent/30 bg-accent/[.06]' : 'border-primary/30 bg-primary/[.05]'}`} data-testid="verify-result"><div className="flex items-start gap-4"><span className={`grid size-12 place-items-center rounded-xl ${verify.data.valid ? 'bg-accent text-accent-foreground' : 'bg-primary text-primary-foreground'}`}>{verify.data.valid ? <BadgeCheck size={25} /> : <X size={25} />}</span><div><h2 className="font-display text-xl font-bold">{verify.data.valid ? 'Verified and active' : 'Pass not valid'}</h2><p className="mt-1 text-sm text-muted-foreground">{verify.data.displayLabel || verify.data.reason || 'The network did not provide further detail.'}</p></div></div><div className="mt-6 grid grid-cols-2 gap-4 border-t border-border pt-4 sm:grid-cols-3"><div><p className="rk-kicker">Record type</p><p className="mt-1 text-sm font-bold">{titleCase(verify.data.verificationType)}</p></div><div><p className="rk-kicker">Reference</p><p className="mt-1 truncate font-mono text-xs font-bold">{verify.data.referenceId || '—'}</p></div><div><p className="rk-kicker">Checked</p><p className="mt-1 text-sm font-bold">{timeLabel(verify.data.verifiedAt)}</p></div></div></div>}</SectionCard><div className="mt-5 flex items-center gap-3 rounded-xl border border-border bg-secondary/45 p-4 text-xs text-muted-foreground"><LockKeyhole size={17} className="shrink-0 text-accent" />Verification requests are read-only and recorded for network accountability.</div></div></Shell>;
}

function ModulesPage() {
  const modules = [{ title: 'Donor wallet', detail: 'Verified identity, eligibility, QR pass and contribution history.', href: '/donor', icon: UserRound, tag: 'People' }, { title: 'SOS response', detail: 'Broadcast urgent need and move through an accountable response state.', href: '/sos', icon: Siren, tag: 'Emergency' }, { title: 'Live inventory', detail: 'See verified units, expiry windows and chain-of-custody events.', href: '/blood-bank', icon: Database, tag: 'Operations' }, { title: 'Hospital command', detail: 'Create requests, match available units and coordinate escalation.', href: '/hospital', icon: Hospital, tag: 'Facilities' }, { title: 'QR verification', detail: 'Confirm donor or unit identity at the moment of handoff.', href: '/verify/scan', icon: QrCode, tag: 'Trust' }, { title: 'AI Guardian', detail: 'Surface risk signals before pressure becomes a shortage.', href: '/authority', icon: ShieldCheck, tag: 'Intelligence' }, { title: 'Lab verification', detail: 'Keep test confirmation and release decisions close to the unit.', href: '/lab', icon: FileCheck2, tag: 'Quality' }, { title: 'Grid oversight', detail: 'Nationwide trends, facilities and immutable activity records.', href: '/authority', icon: MapPin, tag: 'Authority' }]; return <Shell><PageHeader eyebrow="Rakt Kavach / platform surface" title="One grid, every critical workflow." detail="The product surface is designed around the moments where delay costs the most: identity, readiness, matching, verification and response." /><div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">{modules.map(({ title, detail, href, icon: Icon, tag }, index) => <Link href={href} key={title} className={`rk-card rk-animate-in rk-delay-${(index % 3) + 1} group rounded-xl p-5 transition-transform hover:-translate-y-1`} data-testid={`module-card-${title.toLowerCase().replaceAll(' ', '-')}`}><div className="flex items-start justify-between"><span className="grid size-10 place-items-center rounded-lg bg-secondary text-primary"><Icon size={19} /></span><span className="rk-kicker">{tag}</span></div><h2 className="mt-7 font-display text-base font-bold">{title}</h2><p className="mt-2 text-xs leading-5 text-muted-foreground">{detail}</p><span className="mt-5 inline-flex items-center gap-1 text-xs font-bold text-primary">Open module <ArrowRight size={13} className="transition-transform group-hover:translate-x-1" /></span></Link>)}</div><div className="mt-7 rounded-xl bg-sidebar p-6 text-sidebar-foreground md:flex md:items-center md:justify-between"><div><p className="rk-kicker text-sidebar-foreground/50">Designed for continuity</p><h2 className="mt-2 font-display text-xl font-bold">Calm under pressure, explicit by default.</h2><p className="mt-2 max-w-xl text-sm leading-6 text-sidebar-foreground/60">Bilingual-ready labels, installable PWA shell, offline messaging and auditable actions keep the network useful when conditions are not ideal.</p></div><Link href="/founder" className="mt-5 inline-flex items-center gap-2 rounded-lg bg-sidebar-primary px-4 py-2.5 text-xs font-bold text-sidebar-primary-foreground md:mt-0" data-testid="link-modules-founder">View platform health <ArrowRight size={14} /></Link></div></Shell>;
}

function Router() {
  const [location] = useLocation();
  return <ErrorBoundary resetKey={location}><Switch><Route path="/" component={Gateway} /><Route path="/donor" component={DonorPage} /><Route path="/hospital" component={HospitalPage} /><Route path="/blood-bank" component={BloodBankPage} /><Route path="/lab" component={LabPage} /><Route path="/authority" component={AuthorityPage} /><Route path="/founder" component={FounderPage} /><Route path="/sos" component={SosPage} /><Route path="/verify/:token" component={VerifyPage} /><Route path="/modules" component={ModulesPage} /><Route component={NotFound} /></Switch></ErrorBoundary>;
}

function App() {
  return <QueryClientProvider client={queryClient}><TooltipProvider><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}><Router /></WouterRouter><Toaster /></TooltipProvider></QueryClientProvider>;
}

export default App;